import torch
from torch.utils.cpp_extension import load_inline

src = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

__global__ void hinge_kernel(const half* __restrict__ pred,
                             const half* __restrict__ targ,
                             float* __restrict__ sum,
                             const int64_t total_elements,
                             const int64_t inner_dim) {
    // each thread processes a strided chunk
    float local_sum = 0.0f;
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x * gridDim.x;
    for (int64_t i = idx; i < total_elements; i += stride) {
        int64_t b = i / inner_dim;               // batch index
        half p = pred[i];
        half t = targ[b];
        float prod = __half2float(p) * __half2float(t);
        float val = 1.0f - prod;
        if (val < 0.0f) val = 0.0f;
        local_sum += val;
    }

    // block‑level reduction using shared memory (max 1024 threads)
    __shared__ float sdata[1024];
    int lane = threadIdx.x;
    sdata[lane] = local_sum;
    __syncthreads();

    for (int offset = blockDim.x / 2; offset > 0; offset >>= 1) {
        if (lane < offset) {
            sdata[lane] += sdata[lane + offset];
        }
        __syncthreads();
    }

    if (lane == 0) {
        atomicAdd(sum, sdata[0]);
    }
}

torch::Tensor hinge_loss_fp16(torch::Tensor pred, torch::Tensor targ) {
    TORCH_CHECK(pred.is_cuda(), "pred must be a CUDA tensor");
    TORCH_CHECK(targ.is_cuda(), "targ must be a CUDA tensor");
    TORCH_CHECK(pred.dtype() == torch::kHalf, "pred must be fp16");
    TORCH_CHECK(targ.dtype() == torch::kHalf, "targ must be fp16");

    int64_t batch = pred.size(0);
    int64_t inner = pred.numel() / batch;          // elements per sample
    int64_t total = pred.numel();

    auto sum = torch::zeros({1},
                            torch::dtype(torch::kFloat32).device(pred.device()));

    const int threads = 1024;
    const int max_blocks = 65535;
    int blocks = static_cast<int>((total + threads - 1) / threads);
    blocks = (blocks > max_blocks) ? max_blocks : blocks;

    hinge_kernel<<<blocks, threads>>>(
        pred.data_ptr<half>(),
        targ.data_ptr<half>(),
        sum.data_ptr<float>(),
        total,
        inner
    );
    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        printf("CUDA error in hinge_kernel: %s\\n", cudaGetErrorString(err));
    }

    float sum_val = sum.item<float>();
    float mean = sum_val / static_cast<float>(total);
    auto out = torch::full({1},
                           static_cast<half>(mean),
                           torch::dtype(torch::kHalf).device(pred.device()));
    return out.squeeze();
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("hinge_loss_fp16", &hinge_loss_fp16, "Hinge loss (fp16, CUDA)");
}
'''

hinge_ext = load_inline(name="hinge_ext",
                        cpp_sources="",
                        cuda_sources=src,
                        functions=["hinge_loss_fp16"],
                        verbose=False)

class ModelNew(torch.nn.Module):
    def __init__(self):
        super().__init__()
    def forward(self, predictions, targets):
        return hinge_ext.hinge_loss_fp16(predictions, targets)
